  'tradelog.guide.intro.title': 'هذا سجل صفقاتك',
  'tradelog.guide.intro.description':
    'استخدم هذه الصفحة لمراجعة الصفقات واحدة تلو الأخرى، وفرزها، وتصفيتها، وإجراء تغييرات على العديد من الصفقات في نفس الوقت.',
  'tradelog.guide.view-selector.title': 'اختر كيف تريد مراجعة تاريخك',
  'tradelog.guide.view-selector.description':
    'استخدم هذه القائمة للتبديل بين جدول الصفقات الكامل والعروض المجمعة زمنيًا حسب الشهر أو الأسبوع أو اليوم. «الصفقات» هو العرض الافتراضي، بينما تفيد العروض المجمعة عند المراجعة حسب الفترة.',
  'tradelog.guide.filters.title': 'استخدم المرشحات لتضييق نتائج سجل الصفقات',
  'tradelog.guide.filters.description':
    'افتح المرشحات عندما تريد مراجعة حسابات أو أنماط تداول أو وسوم أو أنواع صفقات أو حالات أو تواريخ محددة فقط. يمكنك أيضاً استبعاد أي قيمة لإخراج تلك الصفقات.',
  'tradelog.guide.sorting.title': 'انقر رؤوس الأعمدة لفرز الجدول',
