  'home.guide.quick-links.title': 'الروابط السريعة لاختصار الوصول',
  'home.guide.quick-links.description':
    'توفر الروابط السريعة اختصارات بنقرة واحدة للإجراءات والصفحات الشائعة. وفي وضع التحرير، يمكنك إخفاء الروابط التي لا تريد ظهورها هنا.',
  'home.guide.move-and-resize.title': 'نقل الأدوات وتغيير أحجامها',
  'home.guide.widget-picker.title': 'أضف الأدوات هنا',
  'home.guide.widget-picker.description':
    'عاين الأدوات وأضفها، أو استعد الروابط السريعة المخفية، أو أضف اختصارات للحسابات وأنماط التداول. كل ما هو موجود بالفعل في الصفحة الرئيسية يظهر ضمن «قيد الاستخدام»، حيث يمكنك إزالته.',
  'home.guide.move-and-resize.description':
    'هذه هي المنطقة الرئيسية التي يمكنك إعادة ترتيبها في وضع التحرير. اسحب الأدوات لتحريكها، أو اسحب أداة من ركنها السفلي الأيمن لتغيير حجمها.',
  'home.guide.add-widget.title': 'أضف العناصر إلى الصفحة الرئيسية',
